const templateEffects = sourceEffects.map(effect => {
  const data = effect?.toObject ? effect.toObject() : foundry.utils.deepClone(effect);
  const contract = data?.flags?.["arcane-dnd5e-2014-automation"]?.zoneEventActivity;
