/**
 * Teleport targets INTO caster-centered radius (no animation, uses MidiQOL.moveToken)
 * - 选中或 target 好目标后运行宏
 * - 选中(控制)施法者 token（作为圆心）；若未选中则提示
 * - 点击落点必须在施法者为圆心的半径内；超出会提示并重选
 * - 多目标支持：per-target 或 same-for-all 模式
 */

(async () => {
  const RANGE_FT = 90;       // 传送范围（英尺），可按需修改
  const TIMEOUT_MS = 20000;  // 单次点击超时
  const HIGHLIGHT_COLOR = 0x66ccff;

  // ---------- 帮助函数 ----------
  const feetPerSquare = canvas.scene.grid?.distance ?? 5;
  const gridSize = canvas.grid.size;
  const S = CONST.GRID_SNAPPING_MODES;

  function feetBetweenPts(a, b) {
    return Math.hypot(a.x - b.x, a.y - b.y) / gridSize * feetPerSquare;
  }

  function centerToTopLeft(centerPoint, tokenDocOrCanvasToken) {
    // tokenDocOrCanvasToken may be a Canvas.Token object (has document.width) or TokenDocument
    const tokenGridW = Number(tokenDocOrCanvasToken.document?.width ?? tokenDocOrCanvasToken.document?.source?.width ?? tokenDocOrCanvasToken.width ?? tokenDocOrCanvasToken._source?.width ?? 1);
    const tokenGridH = Number(tokenDocOrCanvasToken.document?.height ?? tokenDocOrCanvasToken.document?.source?.height ?? tokenDocOrCanvasToken.height ?? tokenDocOrCanvasToken._source?.height ?? tokenGridW);
    const halfWpx = (tokenGridW * gridSize) / 2;
    const halfHpx = (tokenGridH * gridSize) / 2;
    return { x: Math.round(centerPoint.x - halfWpx), y: Math.round(centerPoint.y - halfHpx), gridW: tokenGridW, gridH: tokenGridH };
  }

  // 返回舞台上的 token 视觉中心（不用已弃用方法）
  function getTokenCenterPoint(tok) {
    return { x: (tok.center?.x ?? (tok.x + tok.w/2)), y: (tok.center?.y ?? (tok.y + tok.h/2)) };
  }

  // snap 舞台点到网格“格子中心”
  function snapStagePointToGridCenter(stagePoint) {
    try {
      // BaseGrid#getSnappedPoint(point, behavior) -> 返回中心点（舞台坐标）
      return canvas.grid.getSnappedPoint({ x: stagePoint.x, y: stagePoint.y }, { mode: S.CENTER, resolution: 1 });
    } catch (e) {
      // fallback 简单四舍五入到最近格点中心
      return { x: Math.round(stagePoint.x / gridSize) * gridSize, y: Math.round(stagePoint.y / gridSize) * gridSize };
    }
  }

  // 检查指定目标矩形是否与已有 tokens 冲突
  function areaOccupiedByOther(topLeftX, topLeftY, widthPx, heightPx, ignoreId = null) {
    const rectA = new PIXI.Rectangle(topLeftX, topLeftY, widthPx, heightPx);
    return canvas.tokens.placeables.some(t => {
      if (t.id === ignoreId) return false;
      const rectB = new PIXI.Rectangle(t.x, t.y, t.w, t.h);
      return rectA.right  > rectB.left &&
             rectA.left   < rectB.right &&
             rectA.bottom > rectB.top &&
             rectA.top    < rectB.bottom;
    });
  }

  // ---------- 解析施法者与目标 ----------
  const caster = canvas.tokens.controlled[0] ?? token; // 优先使用你控制的 token
  if (!caster) {
    ui.notifications.warn("请先控制（选中）施法者的 Token，再运行此宏");
    return;
  }
  const casterCenter = getTokenCenterPoint(caster);

  // 目标集：优先使用 game.user.targets（玩家 target），否则使用被控制的 tokens（不含 caster）
  let targets = Array.from(game.user.targets ?? []);
  if (targets.length === 0) {
    const ctrl = canvas.tokens.controlled?.filter(t => t.id !== caster.id) ?? [];
    targets = ctrl;
  } else {
    // 如果 targets 包含施法者的 token，移除之
    targets = targets.filter(t => t.id !== caster.id);
  }
  if (targets.length === 0) {
    ui.notifications.warn("请先 target 或选中要传送的一个或多个目标（目标不能包含施法者）");
    return;
  }

  // 如果多个目标，询问模式
  let mode = "per-target";
  if (targets.length > 1) {
    const choice = await new Promise(resolve => {
      new Dialog({
        title: "传送模式",
        content: `<p>检测到 ${targets.length} 个目标。请选择：</p>`,
        buttons: {
          per: { label: "为每个目标分别选择落点", callback: () => resolve("per-target") },
          same: { label: "为所有目标选择同一落点（并验证每个目标是否允许）", callback: () => resolve("same-for-all") },
          cancel: { label: "取消", callback: () => resolve(null) }
        },
        default: "per"
      }).render(true);
    });
    if (!choice) return ui.notifications.info("已取消传送");
    mode = choice;
  }

  // ---------- 绘制以施法者为中心的高亮圆（视觉） ----------
  const maxSquares = Math.max(1, Math.floor(RANGE_FT / feetPerSquare));
  const radiusPx = maxSquares * gridSize;
  const g = new PIXI.Graphics();
  g.lineStyle(2, HIGHLIGHT_COLOR, 0.9);
  g.beginFill(HIGHLIGHT_COLOR, 0.06);
  g.drawCircle(casterCenter.x, casterCenter.y, radiusPx);
  g.endFill();
  g.zIndex = 10000;
  canvas.app.stage.addChild(g);
  ui.notifications.info(`请在施法者高亮圆内选择落点（最多 ${RANGE_FT} 英尺）。点击超出或被占用会提示并重选。`);

  // ---------- 单次点击并 snap 到格子中心（null 表示超时） ----------
  const getClickedSnappedCenter = (ms) => new Promise(resolve => {
    const handler = (event) => {
      try { canvas.app.stage.off("pointerdown", handler); } catch(e){}
      try { canvas.app.stage.removeChild(g); } catch(e){}
      let pos = null;
      try { pos = event.data.getLocalPosition(canvas.app.stage); } catch(e) { pos = null; }
      if (!pos) return resolve(null);
      const snap = snapStagePointToGridCenter(pos);
      resolve(snap);
    };
    canvas.app.stage.on("pointerdown", handler);
    setTimeout(() => {
      try { canvas.app.stage.off("pointerdown", handler); } catch(e){}
      try { canvas.app.stage.removeChild(g); } catch(e){}
      resolve(null);
    }, ms);
  });

  // ---------- 逻辑：per-target 与 same-for-all ----------
  try {
    if (mode === "per-target") {
      for (const tk of targets) {
        // 反复 prompt 直到为该目标选到合法位置
        while (true) {
          // 重新加入高亮（上一次可能被移除）
          if (!canvas.app.stage.children.includes(g)) canvas.app.stage.addChild(g);
          const snapped = await getClickedSnappedCenter(TIMEOUT_MS);
          if (!snapped) { ui.notifications.warn("未检测到点击，请重试"); continue; }

          // 计算该 snapped 的直线距离到 caster 中心
          const dist = feetBetweenPts(snapped, casterCenter);
          if (dist > RANGE_FT + 0.001) {
            ui.notifications.warn(`所选位置距离施法者 ${Math.round(dist)} 英尺，超出 ${RANGE_FT} 英尺，请重新选择`);
            continue;
          }

          // 将 snapped center 转为目标 token 应有的左上与中心（考虑 token 的格宽高）
          const { x: topLeftX, y: topLeftY, gridW, gridH } = (() => {
            const temp = centerToTopLeft(snapped, tk);
            return { x: temp.x, y: temp.y, gridW: temp.gridW, gridH: temp.gridH };
          })();

          // 碰撞检测
          const occupied = areaOccupiedByOther(topLeftX, topLeftY, gridW * gridSize, gridH * gridSize, tk.id);
          if (occupied) { ui.notifications.warn(`${tk.name} 的目标格被占用，请重新选择`); continue; }

          // 计算传入 MidiQOL.moveToken 的 center（以格为单位中心）
          // 当 token grid 大小为偶数时，center 将位于格线交点；当为奇数时，center 位于格子中心
          const centerX = Math.round((topLeftX + (gridW * gridSize) / 2));
          const centerY = Math.round((topLeftY + (gridH * gridSize) / 2));

          // 执行瞬移（仅用 MidiQOL.moveToken，第三个参数 false 表示无动画）
          if (typeof MidiQOL?.moveToken === "function") {
            try {
              await MidiQOL.moveToken(tk, { x: centerX, y: centerY }, false);
              ChatMessage.create({ content: `${tk.name} 已被传送到选定位置（距施法者 ${Math.round(dist)} 英尺）。` });
              console.log(`teleport: ${tk.name} -> center(${centerX},${centerY}), topLeft(${topLeftX},${topLeftY}), grid ${gridW}x${gridH}`);
              break; // 下一目标
            } catch (e) {
              console.error("RealityCollapse: MidiQOL.moveToken failed", e);
              ui.notifications.error("传送失败（检查控制台）");
              break; // 跳出该目标的循环
            }
          } else {
            ui.notifications.error("MidiQOL.moveToken 不可用（宏配置为仅使用该函数进行传送）");
            return;
          }
        } // per-target loop
      } // for each target
    } else { // same-for-all
      while (true) {
        if (!canvas.app.stage.children.includes(g)) canvas.app.stage.addChild(g);
        const snapped = await getClickedSnappedCenter(TIMEOUT_MS);
        if (!snapped) { ui.notifications.warn("未检测到点击，请重试"); continue; }

        const dist = feetBetweenPts(snapped, casterCenter);
        if (dist > RANGE_FT + 0.001) { ui.notifications.warn(`所选位置超出 ${RANGE_FT} 英尺，请重选`); continue; }

        // 需要验证每个 target 的目标矩形是否被占用（按其各自体型）
        let failed = false;
        const planned = [];
        for (const tk of targets) {
          const { x: topLeftX, y: topLeftY, gridW, gridH } = centerToTopLeft(snapped, tk);
          const occupied = areaOccupiedByOther(topLeftX, topLeftY, gridW * gridSize, gridH * gridSize, tk.id);
          if (occupied) { ui.notifications.warn(`${tk.name} 的目标格被占用，选择不合法，请重选`); failed = true; break; }
          planned.push({ tk, topLeftX, topLeftY, gridW, gridH });
        }
        if (failed) continue;

        // 全部合法，执行传送
        for (const p of planned) {
          try {
            const centerX = Math.round((p.topLeftX + (p.gridW * gridSize) / 2));
            const centerY = Math.round((p.topLeftY + (p.gridH * gridSize) / 2));
            await MidiQOL.moveToken(p.tk, { x: centerX, y: centerY }, false);
            ChatMessage.create({ content: `${p.tk.name} 已被传送到共同位置（距施法者 ${Math.round(feetBetweenPts({x:centerX,y:centerY}, casterCenter))} 英尺）。` });
            console.log(`teleport same-for-all: ${p.tk.name} -> center(${centerX},${centerY})`);
          } catch (e) {
            console.error("RealityCollapse: MidiQOL.moveToken failed", e);
            ChatMessage.create({ content: `${p.tk.name} 传送失败（查看控制台）` });
          }
        }
        break;
      } // same-for-all while
    }
  } finally {
    try { canvas.app.stage.removeChild(g); } catch(e){}
  }

  console.log("RealityCollapse: caster-centered teleport finished");
})();

(async () => {
  const caster = actor;
  const target = canvas.tokens.controlled[0]?.actor;
  if (!caster || !target) return ui.notifications.warn("请选择施法者和目标");

  const saveDC = caster.system.attributes.spell.dc;
  if (!saveDC) return ui.notifications.warn("未找到施法者的豁免 DC");

  const damageType = await new Promise(r => new Dialog({
    title: "选择伤害类型",
    content:`<form><label>类型：<select id="dt">
      <option value="fire">火焰</option><option value="cold">寒冷</option>
      <option value="lightning">闪电</option><option value="poison">毒素</option>
      <option value="acid">酸性</option></select></label></form>`,
    buttons:{ ok:{label:"确定",callback:h=>r(h.find("#dt").val())}, cancel:{label:"取消",callback:()=>r(null)} },
    default:"ok"
  }).render(true));
  if (!damageType) return ui.notifications.warn("未选择伤害类型");

  const spellLevel = await new Promise(r => new Dialog({
    title: "选择法术位环级",
    content:`<form><label>环级（最少 2）：<input id="lvl" type="number" min="2" value="2"></label></form>`,
    buttons:{ ok:{label:"确定",callback:h=>r(parseInt(h.find("#lvl").val())||3)}, cancel:{label:"取消",callback:()=>r(null)} },
    default:"ok"
  }).render(true));
  if (!spellLevel) return ui.notifications.warn("未选择环级");

  const extraDice = Math.max(0, spellLevel - 2);

  const item = target.items.find(i => i.name === "龙息");
  if (!item) return ui.notifications.warn("目标无“龙息”物品");

  const formula = `3d6[${damageType}]${extraDice>0? `+${extraDice}d6`: ""}`;

  await item.update({
    [`system.activities.nt6z0FF53gKwBdeL.damage.parts`]: [{
      custom: { enabled: false, formula: "" },
      number: 3 + extraDice,
      denomination: 6,
      bonus: "",
      types: [damageType],
      scaling: { number: 1 }
    }],
    [`system.activities.nt6z0FF53gKwBdeL.save.dc.formula`]: saveDC.toString()
  });

  ui.notifications.info(`更新成功：类型 ${damageType}，伤害 ${formula}，豁免 DC ${saveDC}`);
})();

